node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// 1. Cancel ITEM-59FB3E (Aurora Smart Desk Lamp Pro, \$88)
db.prepare(\"UPDATE order_items SET item_status = 'cancelled', refund_amount = unit_price * quantity, refund_method = 'original_payment' WHERE oi_id = 'ITEM-59FB3E' AND order_id = 'ORD-CCC96C'\").run();

// 2. Return ITEM-4DFEB6 (OXO SoftWorks 3-Piece Mixing Bowl Set, qty 2 x \$42 = \$84)
db.prepare(\"UPDATE order_items SET item_status = 'return_requested', refund_amount = unit_price * quantity, refund_method = 'original_payment' WHERE oi_id = 'ITEM-4DFEB6' AND order_id = 'ORD-CCC96C'\").run();

// Update order-level return_items and return_payment_method_id
db.prepare(\"UPDATE orders SET return_items = 'ITEM-4DFEB6', return_payment_method_id = 'original_payment' WHERE order_id = 'ORD-CCC96C'\").run();

// Verify
const items = db.prepare(\"SELECT oi_id, name, quantity, unit_price, item_status, refund_amount, refund_method FROM order_items WHERE order_id = 'ORD-CCC96C'\").all();
console.log(JSON.stringify(items, null, 2));
const order = db.prepare(\"SELECT status, return_items, return_payment_method_id FROM orders WHERE order_id = 'ORD-CCC96C'\").all();
console.log(JSON.stringify(order, null, 2));
"
